async function callCatalog(offset) {
  const response = await fetch(`${url.replace(/\/+$/, '')}/rest/v1/rpc/get_public_storefront_catalog_page`, {
    method: 'POST',
    headers: {apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json'},
