    if (cartStorageRecovery) {
      throw new Error('السلة المحفوظة تحتاج معالجة قبل تحديث السعر أو المخزون.');
    }
    if (unresolvedCheckoutAttempt) {
      throw new Error('يوجد طلب غير محسوم. أكمل استرداده قبل تحديث السلة أو بدء طلب جديد.');
    }
    const expectedCartRevision = commerceSnapshot.cart.envelope?.revision;
    const snapshotProductIds = Array.from(
      new Set(itemsToRefresh
        .filter((item) => item.commercialLineKind !== 'configurable_parcel')
        .map((item) => item.productId)
        .filter(Boolean))
    );
    const parcelFamilyIds = Array.from(new Set(itemsToRefresh.flatMap((item) =>
      item.commercialLineKind === 'configurable_parcel' ? [item.familyProductId] : []
    )));
    if (snapshotProductIds.length === 0 && parcelFamilyIds.length === 0) return { items: [] };

    const snapshotKey = [...snapshotProductIds, ...parcelFamilyIds].sort().join(',');
    if (pendingCartSnapshotRef.current?.key === snapshotKey) {
      return pendingCartSnapshotRef.current.promise;
    }

    const request = (async () => {
      setIsRefreshingCart(true);
      try {
        const [snapshotProducts, parcelResponse] = await Promise.all([
          snapshotProductIds.length > 0 ? fetchPublicCartSnapshot(snapshotProductIds) : Promise.resolve([]),
          parcelFamilyIds.length > 0
            ? fetchPublicConfigurableParcelOptions(parcelFamilyIds)
            : Promise.resolve(null),
        ]);
        const reconciliation = reconcileCartSnapshot(
          itemsToRefresh,
          snapshotProducts,
          snapshotProductIds
        );
        const optionByFamily = new Map(parcelResponse?.options.map((option) => [option.familyProductId, option]) ?? []);
        const parcelItems = reconciliation.items.map((item) => {
          if (item.commercialLineKind !== 'configurable_parcel') return item;
          const option = optionByFamily.get(item.familyProductId);
          if (
            !parcelResponse?.guestCreationEnabled ||
            !option ||
            option.parcelConfigurationId !== item.parcelConfigurationId ||
            option.configurationRevision !== item.configurationRevision ||
            option.unitsPerParcel !== item.capacity
          ) {
            throw new Error('تغيّر إعداد أحد الطرود. افتح المنتج وراجع تكوينه قبل المتابعة.');
          }
          return {
            ...item,
            unitPriceInMinorUnits: option.parcelPriceInMinorUnits,
            saleUnitNameAr: option.saleUnitNameAr,
          };
        });
        const required = requiredBaseUnitsByProductId(parcelItems);
        for (const option of parcelResponse?.options ?? []) {
          for (const component of option.components) {
            if ((required.get(component.productId) ?? 0) > component.availableQuantity) {
              throw new Error(`الكمية المطلوبة من ${component.flavorNameAr || component.nameAr} لم تعد متاحة.`);
            }
          }
        }
        const persistedItems = await mutateCart((currentItems) =>
          reconcileCartSnapshot(
            currentItems,
            snapshotProducts,
            snapshotProductIds
          ).items.map((item) => {
            if (item.commercialLineKind !== 'configurable_parcel') return item;
            const option = optionByFamily.get(item.familyProductId);
            return option && option.configurationRevision === item.configurationRevision
              ? { ...item, unitPriceInMinorUnits: option.parcelPriceInMinorUnits, saleUnitNameAr: option.saleUnitNameAr }
              : item;
          }),
          expectedCartRevision
        );

        const notices: string[] = [];
        if (reconciliation.priceChanges > 0) {
          notices.push('تم تحديث سعر بعض الأصناف.');
        }
        if (reconciliation.quantityAdjustments > 0) {
          notices.push('تم تعديل الكمية إلى المتاح حاليًا.');
        }
        if (reconciliation.removedUnavailableItems > 0) {
          notices.push('تمت إزالة أصناف لم تعد متاحة للبيع.');
        }
        setCartSnapshotNotice(notices.length > 0 ? notices.join(' ') : null);
        return { items: persistedItems };
      } finally {
        setIsRefreshingCart(false);
      }
    })();

    pendingCartSnapshotRef.current = { key: snapshotKey, promise: request };
    try {
      return await request;
    } finally {
      if (pendingCartSnapshotRef.current?.promise === request) {
        pendingCartSnapshotRef.current = null;
      }
    }
  }, [cartItems, cartStorageRecovery, commerceSnapshot.cart.envelope?.revision, mutateCart, unresolvedCheckoutAttempt]);

  const openCart = useCallback((itemsToRefresh?: CartItem[]) => {
    setCartOpen(true);
    if (cartStorageRecovery) return;
    void refreshCartSnapshot(itemsToRefresh).catch((error: unknown) => {
      const message = error instanceof Error
        ? error.message
        : 'تعذر التحقق من سعر ومخزون السلة. حاول مرة أخرى.';
      setCartSnapshotNotice(message);
    });
  }, [cartStorageRecovery, refreshCartSnapshot]);

  const openProductDetails = useCallback((product: CatalogProduct) => {
    setLinkedProduct(null);
    setSelectedProductId(product.id);
    setSelectedProductVariantId(null);
    const nextPath = getProductPath(product.sku || product.id);
    if (window.location.pathname === nextPath && !window.location.hash) return;
    changeStoreLocation(nextPath, window.location.pathname.startsWith('/product/'));
  }, []);

  const closeProductDetails = useCallback(() => {
    setSelectedProductId(null);
    setSelectedProductVariantId(null);
    setLinkedProduct(null);
    if (readStoreLocationRoute(window.location).productKey) {
      const nextPath = selectedCategoryDetails
        ? getCategoryPath(getCategorySlug(selectedCategoryDetails))
        : getStorePagePath(activePage);
      changeStoreLocation(nextPath, true);
    }
  }, [activePage, selectedCategoryDetails]);

  const updateCartQuantity = (localLineId: string, quantity: number) => {
    if (cartStorageRecovery) return;
    if (lockedLineIds.has(localLineId)) {
      showToast('هذا السطر مرتبط بطلب غير محسوم. أضف كمية جديدة كسطر مستقل.', 'info');
      return;
    }
    if (quantity <= 0) {
      setCartItems((items) =>
        items.filter((item) => item.localLineId !== localLineId)
      );
      return;
    }

    setCartItems((items) =>
      items.map((item) =>
        item.localLineId === localLineId && item.commercialLineKind !== 'configurable_parcel'
          ? {
              ...item,
              localRevision: item.localRevision + 1,
              quantity: Math.min(
                Math.max(1, Math.floor(quantity)),
                item.maxAvailablePackages
              ),
            }
          : item
      )
    );
  };

  // Catalogue counters aggregate legacy parcels;the cart writer takes a line ID.
  // Resolve only an editable parcel line,never a base-unit or frozen line.
  const updateCatalogCartQuantity = (productId: string, quantity: number) => {
    if (cartStorageRecovery) return;
    const currentQuantity = cartQuantityByProduct.get(productId) ?? 0;
    if (quantity > currentQuantity) {
      const product = sellableProducts.find(candidate => candidate.id === productId);
      if (product) addQuantityToCart(product, quantity - currentQuantity);
      return;
    }
    if (quantity >= currentQuantity) return;
    const line = cartItems.find(item => item.productId === productId
      && item.commercialLineKind === 'legacy_single_sku_parcel'
      && !lockedLineIds.has(item.localLineId));
    if (!line) {
      showToast('الكمية مرتبطة بطلب غير محسوم ولا يمكن إنقاصها الآن.', 'info');
      return;
    }
    updateCartQuantity(line.localLineId, Math.max(0, line.quantity - (currentQuantity - quantity)));
  };

  const resetCatalogView = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setAvailabilityFilter('all');
    setSortOption('recommended');
    setSelectedBrand('all');
    setSelectedSaleUnit('all');
    setCatalogOffset(0);
  };

  const navigateStorePage = useCallback((page: StorePage) => {
    setActivePage(page);
    changeStoreLocation(getStorePagePath(page));
    window.requestAnimationFrame(() => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }, []);

  const scrollToCatalog = () => {
    setActivePage('catalog');
    changeStoreLocation(getStorePagePath('catalog'));
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        document.getElementById('catalog-products')?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      });
    });
  };

  const showAllProducts = () => {
    resetCatalogView();
    scrollToCatalog();
  };

  const openFavorites = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setAvailabilityFilter('all');
    setSortOption('recommended');
    setSelectedBrand('all');
    setSelectedSaleUnit('all');
    setCatalogOffset(0);
    navigateStorePage('favorites');
  };

  const toggleProductFavorite = (product: CatalogProduct) => {
    setFavoriteProductIds((current) => {
      const isFavorite = current.includes(product.id);
      showToast(
        isFavorite
          ? `تمت إزالة ${product.nameAr} من المفضلة.`
          : `تمت إضافة ${product.nameAr} إلى المفضلة.`
      );
      return isFavorite
        ? current.filter((productId) => productId !== product.id)
        : [...current, product.id];
    });
  };

  const selectCatalogCategory = useCallback((categoryId: string) => {
    setActivePage('catalog');
    setSelectedCategory(categoryId);
    setSearchQuery('');
    setAvailabilityFilter('all');
    setCatalogOffset(0);
    setCategoriesOpen(false);
    const category = catalogCategories.find((candidate) => candidate.id === categoryId);
    changeStoreLocation(
      category ? getCategoryPath(getCategorySlug(category)) : getStorePagePath('catalog')
    );
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        document.getElementById('catalog-products')?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      });
    });
  }, [catalogCategories]);

  const openCheckout = async () => {
    if (commerceReview) {
      setCartOpen(true);
      showToast(commerceReview.message, 'error');
      return;
    }
    if (cartStorageRecovery) {
      setCartOpen(true);
      showToast('لا يمكن إتمام الطلب قبل معالجة السلة المحفوظة.', 'error');
      return;
    }
    if (
      checkoutAttempt &&
      (checkoutAttempt.serverState === 'UNKNOWN' ||
        checkoutAttempt.serverState === 'SUCCEEDED' ||
        checkoutAttempt.reviewRequired)
    ) {
      setCartOpen(false);
      setCheckoutOpen(true);
      return;
    }
    let currentCartItems: CartItem[];
    try {
      currentCartItems = (await refreshCartSnapshot()).items;
    } catch (error) {
      showToast(
        error instanceof Error
          ? error.message
          : 'تعذر التحقق من سعر ومخزون السلة. حاول مرة أخرى.',
        'error'
      );
      return;
    }
    if (currentCartItems.length === 0) {
      showToast('السلة فارغة. أضف طردًا أولًا.', 'info');
      return;
    }
    if (!settingsTrusted) {
      showToast(
        settingsUnavailable
          ? 'تعذر التحقق من إعدادات الطلب والتوصيل. أعد المحاولة.'
          : 'جارٍ التحقق من إعدادات الطلب والتوصيل.',
        'info'
      );
      return;
    }
    if (!storefrontSettings.ordersEnabled) {
      showToast('الطلبات متوقفة مؤقتًا من إدارة المتجر. تواصل معنا عبر واتساب.', 'info');
      return;
    }
    const refreshedCartSubtotal = calculateCartSubtotal(currentCartItems);
    if (refreshedCartSubtotal < storefrontSettings.minimumOrderInMinorUnits) {
      showToast(`الحد الأدنى للطلب هو ${(storefrontSettings.minimumOrderInMinorUnits / 1000).toFixed(3)} د.أ.`, 'info');
      return;
    }
    setCartOpen(false);
    setCheckoutOpen(true);
  };

  const handleCartStorageRecovery = async () => {
    if (!cartStorageRecovery) return;
    try {
      const action = cartStorageRecovery.validItems.length > 0
        ? 'KEEP_VALID_ITEMS'
        : 'RESET_CART';
      await resolveCartRecovery(cartStorageRecovery, action);
      const pendingSuccess = checkoutCoordinator.read().attempt;
      showToast(
        action === 'KEEP_VALID_ITEMS'
          ? 'تم الاحتفاظ بالعناصر السليمة بعد موافقتك، وحُفظت نسخة استرداد محلية.'
          : 'تمت إعادة ضبط السلة بعد موافقتك، وحُفظت نسخة استرداد محلية.'
      );
      if (
        pendingSuccess.status === 'VALID' &&
        pendingSuccess.attempt?.serverState === 'SUCCEEDED'
      ) {
        setCartOpen(false);
        setCheckoutOpen(true);
      }
    } catch (error) {
      showToast(
        error instanceof Error
          ? error.message
          : 'تعذر معالجة السلة بأمان. لم تُحذف البيانات الأصلية.',
        'error'
      );
    }
  };

  const handleOrderCreated = (
    receipt: GuestOrderReceipt,
    submittedItems: CartItem[]
  ) => {
    refreshCommerce();
    setPreferredPromotionCode('');
    setLastGuestOrder({ version: 2, orderNumber: receipt.orderNumber, items: structuredClone(submittedItems), createdAt: Date.now() });
    showToast(`تم تسجيل الطلب ${receipt.orderNumber} بنجاح.`);
    void loadCatalog(true, true);
  };

  const openCreatedOrderTracking = (receipt: GuestOrderReceipt) => {
    if (!receipt.trackingToken) {
      showToast('تعذر تجهيز رابط متابعة هذا الطلب. استخدم رقم الطلب والهاتف من صفحة المتابعة.', 'info');
      return;
    }

    const nextHash = `#track=${encodeURIComponent(receipt.trackingToken)}`;
    window.history.pushState(null, '', nextHash);
    window.dispatchEvent(new PopStateEvent('popstate'));
  };

  const usePromotionOffer = (offer: StorefrontOffer) => {
    setPreferredPromotionCode(offer.code);
    void navigator.clipboard?.writeText(offer.code).catch(() => undefined);
    showToast(`تم تجهيز رمز ${offer.code}. سيظهر تلقائيًا عند إتمام الطلب.`);
    if (cartItems.length > 0) {
      openCart();
      return;
    }
    showAllProducts();
  };

  const openPromotionOffers = () => navigateStorePage('offers');

  const repeatLastOrder = () => {
    if (cartStorageRecovery) {
      setCartOpen(true);
      showToast('راجع حالة السلة المحفوظة قبل استعادة طلب سابق.', 'info');
      return;
    }
    if (unresolvedCheckoutAttempt) {
      showToast('أكمل استرداد محاولة الطلب الحالية قبل استعادة طلب سابق.', 'info');
      return;
    }
    if (!lastGuestOrder || pendingRepeatLastOrderRef.current) return;

    const request = (async () => {
      setIsRepeatingLastOrder(true);
      try {
        const scalarItems = lastGuestOrder.items.filter(
          (item) => item.commercialLineKind !== 'configurable_parcel'
        );
        const configurableItems = lastGuestOrder.items.filter(
          (item): item is ConfigurableParcelCartItem => item.commercialLineKind === 'configurable_parcel'
        );
        const [snapshotProducts, parcelResponse] = await Promise.all([
          scalarItems.length > 0
            ? fetchPublicCartSnapshot(scalarItems.map((item) => item.productId))
            : Promise.resolve([]),
          configurableItems.length > 0
            ? fetchPublicConfigurableParcelOptions(configurableItems.map((item) => item.familyProductId))
            : Promise.resolve(null),
        ]);
        const restoration = restoreLastOrderFromSnapshot(
          scalarItems,
          snapshotProducts
        );
        const optionByFamily = new Map(parcelResponse?.options.map((option) => [option.familyProductId, option]) ?? []);
        const restoredParcels = configurableItems.flatMap((saved) => {
          const option = optionByFamily.get(saved.familyProductId);
          if (
            !parcelResponse?.guestCreationEnabled ||
            !option ||
            option.parcelConfigurationId !== saved.parcelConfigurationId ||
            option.configurationRevision !== saved.configurationRevision ||
            option.unitsPerParcel !== saved.capacity
          ) return [];
          const availableByProduct = new Map(option.components.map((component) => [component.productId, component.availableQuantity]));
          const required = requiredBaseUnitsByProductId([saved]);
          if ([...required].some(([productId, quantity]) => quantity > (availableByProduct.get(productId) ?? 0))) return [];
          return [{
            ...saved,
            localLineId: crypto.randomUUID(),
            localRevision: 1,
            unitPriceInMinorUnits: option.parcelPriceInMinorUnits,
            parcelInstances: saved.parcelInstances.map(duplicateParcelInstance),
          }];
        });
        restoration.items.push(...restoredParcels);
        restoration.unavailableItems += configurableItems.length - restoredParcels.length;
        const notices: string[] = [];
        if (restoration.unavailableItems > 0) {
          notices.push('بعض أصناف الطلب السابق لم تعد متاحة للبيع ولم تُضف إلى السلة.');
        }
        if (restoration.quantityAdjustments > 0) {
          notices.push('تم تعديل كمية بعض الأصناف إلى المتاح حاليًا.');
        }

        if (restoration.items.length === 0) {
          const notice = notices[0] ?? 'أصناف الطلب السابق لم تعد متاحة للبيع.';
          setCartSnapshotNotice(notice);
          showToast(notice, 'info');
          return;
        }

        const successNotice = `تمت إعادة ${restoration.items.length.toLocaleString('ar-JO')} أصناف من طلبك السابق بالأسعار الحالية.`;
        const notice = [successNotice, ...notices].join(' ');
        await replaceCart(restoration.items);
        setCartSnapshotNotice(notice);
        setCartOpen(true);
        showToast(notice, notices.length > 0 ? 'info' : 'success');
      } catch {
        const notice = 'تعذر التحقق من أصناف الطلب السابق. حاول مرة أخرى.';
        setCartSnapshotNotice(notice);
        showToast(notice, 'error');
      } finally {
        setIsRepeatingLastOrder(false);
      }
    })();

    pendingRepeatLastOrderRef.current = request;
    void request.finally(() => {
      if (pendingRepeatLastOrderRef.current === request) {
        pendingRepeatLastOrderRef.current = null;
      }
    });
  };

  return (
    <div className="min-h-screen bg-[#fbf7f0] text-slate-900">
      <StoreHeader
        activePage={activePage}
        searchQuery={searchQuery}
        onSearchChange={(value) => {
          setSearchQuery(value);
          setCatalogOffset(0);
          if (value.trim() && activePage !== 'catalog') {
            setActivePage('catalog');
            changeStoreLocation(getStorePagePath('catalog'));
          }
        }}
        cartPackages={cartPackages}
        cartSummary={formatCartQuantitySummary(cartItems)}
        favoritesCount={favoriteProductIds.length}
        favoritesActive={favoritesActive}
        onCartOpen={() => openCart()}
        onFavoritesOpen={openFavorites}
        onMenuOpen={() => setCategoriesOpen(true)}
        onCategoriesOpen={() => navigateStorePage('categories')}
        onHome={() => navigateStorePage('home')}
        onAllProducts={showAllProducts}
        onOffers={openPromotionOffers}
        onAbout={() => navigateStorePage('about')}
        onTrackOrder={() => setTrackingOpen(true)}
        onRefresh={() => void loadCatalog(true, true)}
        isRefreshing={isRefreshing}
        suggestions={searchSuggestions}
        searchOpenSignal={searchOpenSignal}
        onSuggestionSelect={(product) => { setSearchQuery(''); openProductDetails(product); }}
      />

      <NetworkStatusBanner
        isOnline={isOnline}
        refreshError={products.length > 0 ? loadError : null}
        lastUpdatedAt={lastUpdatedAt}
        isRetrying={isRefreshing}
        onRetry={() => void loadCatalog(true, true)}
      />

      {!settingsTrusted && (
        <section
          role={settingsUnavailable ? 'alert' : 'status'}
          aria-live="polite"
          className="border-b border-amber-200 bg-amber-50 px-4 py-3 text-center text-xs font-black text-amber-900"
        >
          <div className="mx-auto flex max-w-4xl flex-wrap items-center justify-center gap-3">
            <span>
              {settingsUnavailable
                ? 'تعذر تحميل إعدادات الطلب والتوصيل. لن نعرض رسومًا أو حدًا أدنى غير موثوقين.'
                : 'جارٍ التحقق من إعدادات الطلب والتوصيل.'}
            </span>
            {settingsUnavailable && (
              <button
                type="button"
                onClick={() => void loadStorefrontSettings(true)}
                className="rounded-xl border border-amber-300 bg-white px-3 py-1.5 text-[11px] font-black text-amber-900"
              >
                إعادة المحاولة
              </button>
            )}
          </div>
        </section>
      )}

      {settingsTrusted && !storefrontSettings.ordersEnabled && (
        <div className="border-b border-amber-200 bg-amber-50 px-4 py-3 text-center text-xs font-black text-amber-800">
          الطلبات متوقفة مؤقتًا، لكن يمكنك تصفح الأصناف والتواصل معنا عبر واتساب.
        </div>
      )}

      <main>
        {activePage === 'home' && (
          <>
        <StoreHero
          productsCount={catalogTotal}
          categoriesCount={catalogCategories.length}
          availablePackages={availablePackages}
          onBrowseProducts={showAllProducts}
          announcementText={
            settingsTrusted
              ? storefrontSettings.announcementText
              : 'تصفح أصناف الجملة المتوفرة حاليًا'
          }
        />

        {settingsTrusted && storefrontSettings.showOffers && (
          <PromotionOffers
            offers={storefrontOffers}
            onUseOffer={usePromotionOffer}
          />
        )}

        <HomeCategoryMosaic
          categories={catalogCategories}
          products={products}
          onSelect={selectCatalogCategory}
          onShowAll={() => navigateStorePage('categories')}
        />

        <MerchandisingSections
          newest={settingsTrusted && storefrontSettings.showNewestProducts ? newestProducts : []}
          bestSellers={settingsTrusted && storefrontSettings.showBestSellers ? bestSellerProducts : []}
          offers={settingsTrusted && storefrontSettings.showOffers ? offerProducts : []}
          lowStock={settingsTrusted && storefrontSettings.showLowStock ? lowStockProducts : []}
          isLoading={featuredProductsLoading}
          error={featuredProductsError}
          onRetry={() => void loadFeaturedProducts()}
          onOpenProduct={openProductDetails}
          onShowAll={showAllProducts}
        />
          </>
        )}

        {activePage === 'categories' && (
          <section id="categories-page" className="min-h-[70vh] bg-gradient-to-b from-blue-50/50 to-[#fbf7f0] py-10 sm:py-14">
            <div className="mx-auto max-w-7xl px-4 lg:px-8">
              <CategoryShowcase
                categories={catalogCategories}
                products={products}
                selectedCategory={selectedCategory}
                totalProducts={products.length}
                onSelect={selectCatalogCategory}
              />
            </div>
          </section>
        )}

        {activePage === 'offers' && (
          <OffersPage
            offers={settingsTrusted && storefrontSettings.showOffers ? storefrontOffers : []}
            isLoading={offersLoading}
            error={offersLoadError}
            onRetry={() => {
              setOffersLoading(true);
              void loadStorefrontOffers(true);
            }}
            onBrowseProducts={showAllProducts}
            onUseOffer={usePromotionOffer}
          />
        )}

        {activePage === 'about' && (
          <AboutStorePage
            onBrowseProducts={showAllProducts}
            whatsappUrl={storeWhatsappUrl}
            onTrackOrder={() => setTrackingOpen(true)}
            settings={settingsTrusted ? storefrontSettings : null}
          />
        )}

        {activePage === 'catalog' && (
        <section id="catalog" className="relative z-10 min-h-[70vh] py-8 pb-24 sm:py-12">
          <div className="mx-auto max-w-7xl px-4 lg:px-8">
            <div className="rounded-[2rem] border border-white/70 bg-white/95 p-4 shadow-xl shadow-slate-900/5 backdrop-blur sm:p-6">
              <div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
                <div>
                  <div className="inline-flex items-center gap-2 text-blue-700">
                    <Boxes className="h-5 w-5" />
                    <span className="text-xs font-black">الكتالوج المباشر</span>
                  </div>
                  <h2 className="mt-2 text-2xl font-black text-slate-950">
                    أصناف الجملة المتوفرة
                  </h2>
                  <p className="mt-2 text-xs leading-6 text-slate-500">
                    كل كمية هنا محسوبة بوحدة البيع الموضّحة للصنف ومحتواها.
                  </p>
                </div>

                <div className="flex flex-col items-start gap-2 text-[10px] font-bold text-slate-600 sm:items-end">
                  <span
                    className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 ${
                      isOnline && !loadError
                        ? 'bg-emerald-50 text-emerald-700'
                        : 'bg-amber-50 text-amber-700'
                    }`}
                  >
                    {isOnline && !loadError ? (
                      <CheckCircle2 className="h-3.5 w-3.5" />
                    ) : (
                      <AlertTriangle className="h-3.5 w-3.5" />
                    )}
                    {isOnline && !loadError
                      ? 'متصل بـSupabase'
                      : isOnline
                        ? 'آخر تحديث لم يكتمل'
                        : 'بدون اتصال'}
                  </span>
                  {lastUpdatedAt && (
                    <span>
                      آخر تحديث:{' '}
                      {lastUpdatedAt.toLocaleTimeString('ar-JO', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </span>
                  )}
                </div>
              </div>

              <div className="mt-4 grid gap-3 border-t border-slate-100 pt-4 lg:grid-cols-[1fr_auto] lg:items-end">
                <div className="flex flex-wrap gap-2">
                {(
                    [
                      {
                        value: 'all',
                        label: `كل الحالات (${catalogTotal.toLocaleString(
                          'ar-JO'
                        )})`,
                      },
                      {
                        value: 'available',
                        label: `متوفر (${availableProductsCount.toLocaleString(
                          'ar-JO'
                        )})`,
                      },
                      {
                        value: 'low_stock',
                        label: `قارب على النفاد (${lowStockProductsCount.toLocaleString(
                          'ar-JO'
                        )})`,
                      },
                    ] as const
                  ).map((filter) => (
                    <button
                      type="button"
                      key={filter.value}
                      onClick={() => {
                        setCatalogOffset(0);
                        setAvailabilityFilter(filter.value);
                      }}
                      className={`rounded-2xl px-3.5 py-2 text-[10px] font-black transition sm:text-xs ${
                        availabilityFilter === filter.value
                          ? 'bg-emerald-800 text-white shadow-md shadow-emerald-900/15'
                          : 'border border-slate-200 bg-slate-50 text-slate-600 hover:border-emerald-200'
                      }`}
                    >
                      {filter.label}
                    </button>
                  ))}
                </div>

                <label className="flex min-w-52 items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2">
                  <ListFilter className="h-4 w-4 shrink-0 text-blue-700" />
                  <span className="text-[10px] font-black text-slate-500">
                    ترتيب:
                  </span>
                  <select
                    value={sortOption}
                    onChange={(event) => {
                      setCatalogOffset(0);
                      setSortOption(event.target.value as CatalogSortOption);
                    }}
                    className="min-w-0 flex-1 bg-transparent text-xs font-black text-slate-800 outline-none"
                  >
                    <option value="recommended">المقترح</option>
                    <option value="name_asc">الاسم</option>
                    <option value="price_asc">السعر: الأقل أولًا</option>
                    <option value="price_desc">السعر: الأعلى أولًا</option>
                    <option value="stock_desc">الأكثر توفرًا</option>
                  </select>
                </label>
              </div>

              <div className="mt-3 grid gap-2 sm:grid-cols-2">
                <label className="flex items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2 text-[10px] font-black text-slate-500">الماركة<select value={selectedBrand} onChange={(event) => { setCatalogOffset(0); setSelectedBrand(event.target.value); }} className="min-w-0 flex-1 bg-transparent text-xs font-black text-slate-800 outline-none"><option value="all">جميع الماركات</option>{brands.map((brand) => <option key={brand.id} value={brand.id}>{brand.nameAr}</option>)}</select></label>
              </div>

              {lastGuestOrder && <button type="button" onClick={repeatLastOrder} disabled={isRepeatingLastOrder} className="mt-3 w-full rounded-2xl border border-blue-200 bg-blue-50 px-4 py-3 text-xs font-black text-blue-800 disabled:cursor-wait disabled:opacity-60">{isRepeatingLastOrder ? 'جارٍ التحقق من أصناف الطلب...' : `إعادة آخر طلب (${lastGuestOrder.orderNumber})`}</button>}

              <div className="mt-3 flex flex-wrap items-center justify-between gap-2 px-1">
                <p className="text-[10px] font-bold text-slate-600">
                  عرض {filteredProducts.length.toLocaleString('ar-JO')} من{' '}
                  {catalogTotal.toLocaleString('ar-JO')} صنف
                </p>
                {hasActiveCatalogView && (
                  <button
                    type="button"
                    onClick={resetCatalogView}
                    className="inline-flex items-center gap-1.5 text-[10px] font-black text-blue-700 transition hover:text-blue-900"
                  >
                    <RotateCcw className="h-3.5 w-3.5" />
                    إعادة ضبط العرض
                  </button>
                )}
              </div>
            </div>

            <div id="catalog-products" className="scroll-mt-40">
            {isLoading ? (
              <div className="mt-6 grid grid-cols-2 gap-3 min-[380px]:grid-cols-3 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4">
                {Array.from({ length: 8 }).map((_, index) => (
                  <div
                    key={index}
                    className="h-[430px] animate-pulse rounded-[1.75rem] border border-slate-200 bg-white p-4"
                  >
                    <div className="h-52 rounded-3xl bg-slate-100" />
                    <div className="mt-5 h-4 w-2/3 rounded bg-slate-100" />
                    <div className="mt-3 h-3 w-1/3 rounded bg-slate-100" />
                    <div className="mt-7 h-16 rounded-2xl bg-slate-100" />
                  </div>
                ))}
              </div>
            ) : loadError && products.length === 0 ? (
              <div className="mt-6 rounded-[2rem] border border-rose-200 bg-white p-10 text-center">
                <AlertTriangle className="mx-auto h-10 w-10 text-rose-500" />
                <h3 className="mt-4 text-lg font-black text-slate-900">
                  تعذر فتح كتالوج الجملة
                </h3>
                <p className="mx-auto mt-2 max-w-xl text-xs leading-6 text-slate-500">
                  {loadError}
                </p>
                <button
                  type="button"
                  onClick={() => void loadCatalog(false, true)}
                  className="mt-5 inline-flex items-center gap-2 rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white"
                >
                  <RefreshCw className="h-4 w-4" />
                  إعادة المحاولة
                </button>
              </div>
            ) : filteredProducts.length === 0 ? (
              <div className="mt-6 rounded-[2rem] border border-slate-200 bg-white p-10 text-center">
                {searchQuery ? (
                  <SearchX className="mx-auto h-10 w-10 text-slate-400" />
                ) : (
                  <PackageSearch className="mx-auto h-10 w-10 text-slate-400" />
                )}
                <h3 className="mt-4 font-black text-slate-900">
                  {searchQuery
                    ? 'لا توجد نتيجة مطابقة'
                    : selectedCategoryDetails
                      ? `لا توجد أصناف داخل ${selectedCategoryDetails.nameAr} حاليًا`
                    : 'لا توجد أصناف جملة جاهزة للعرض'}
                </h3>
                <p className="mt-2 text-xs leading-6 text-slate-500">
                  {searchQuery
                    ? 'جرّب اسمًا أو SKU مختلفًا.'
                    : selectedCategoryDetails
                      ? 'عند إسناد صنف لهذا القسم من تطبيق الإدارة سيظهر هنا تلقائيًا.'
                    : 'عند إضافة صنف مكتمل من تطبيق الإدارة سيظهر هنا تلقائيًا.'}
                </p>
              </div>
            ) : (
              <div data-testid="catalog-products-grid" className="mt-6 grid grid-cols-2 gap-3 min-[380px]:grid-cols-3 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4">
                {filteredProducts.map((product) => (
                  <ProductCard
                    key={product.id}
                    product={product}
                    cartQuantity={catalogCartQuantityByProduct.get(product.id) || 0}
                    reservedQuantity={reservedBaseUnits.get(product.id) ?? 0}
                    isFavorite={favoriteProductIds.includes(product.id)}
                    onAdd={addToCart}
                    onQuantityChange={updateCatalogCartQuantity}
                    onOpenDetails={openProductDetails}
                    onToggleFavorite={toggleProductFavorite}
                  />
                ))}
              </div>
            )}
            {!isLoading && !loadError && catalogTotal > STOREFRONT_CATALOG_PAGE_SIZE && (
              <nav className="mt-8 flex items-center justify-center gap-3" aria-label="صفحات الكتالوج">
                <button
                  type="button"
                  onClick={() => {
                    setCatalogOffset((current) => Math.max(0, current - STOREFRONT_CATALOG_PAGE_SIZE));
                    document.getElementById('catalog-products')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
                  }}
                  disabled={catalogOffset === 0}
                  className="rounded-2xl border border-slate-200 bg-white px-4 py-2.5 text-xs font-black text-slate-700 transition enabled:hover:border-blue-300 enabled:hover:text-blue-700 disabled:cursor-not-allowed disabled:opacity-45"
                >
                  السابق
                </button>
                <span className="text-xs font-black text-slate-500">
                  صفحة {Math.floor(catalogOffset / STOREFRONT_CATALOG_PAGE_SIZE) + 1} من {Math.max(1, Math.ceil(catalogTotal / STOREFRONT_CATALOG_PAGE_SIZE))}
                </span>
                <button
                  type="button"
                  onClick={() => {
                    setCatalogOffset((current) => current + STOREFRONT_CATALOG_PAGE_SIZE);
                    document.getElementById('catalog-products')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
                  }}
                  disabled={catalogOffset + STOREFRONT_CATALOG_PAGE_SIZE >= catalogTotal}
                  className="rounded-2xl bg-blue-700 px-4 py-2.5 text-xs font-black text-white transition enabled:hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-45"
                >
                  التالي
                </button>
              </nav>
            )}
            </div>
          </div>
        </section>
        )}

        {activePage === 'favorites' && (
          <section
            id="favorites"
            data-testid="favorites-page"
            className="relative z-10 min-h-[70vh] py-8 pb-24 sm:py-12"
          >
            <div className="mx-auto max-w-7xl px-4 lg:px-8">
              <div className="rounded-[2rem] border border-rose-100 bg-white/95 p-5 shadow-xl shadow-slate-900/5 backdrop-blur sm:p-7">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                  <div>
                    <div className="inline-flex items-center gap-2 text-rose-600">
                      <Heart className="h-5 w-5 fill-current" />
                      <span className="text-xs font-black">قائمة خاصة بك</span>
                    </div>
                    <h2 className="mt-2 text-2xl font-black text-slate-950">
                      المنتجات المفضلة
                    </h2>
                    <p className="mt-2 text-xs leading-6 text-slate-500">
                      احتفظنا باختياراتك على هذا الجهاز لتعود إليها بسهولة.
                    </p>
                  </div>
                  {favoriteProductIds.length > 0 && (
                    <span className="inline-flex w-fit items-center rounded-full bg-rose-50 px-3 py-1.5 text-xs font-black text-rose-700">
                      {favoriteProductIds.length.toLocaleString('ar-JO')} منتجات محفوظة
                    </span>
                  )}
                </div>

                {favoriteProductIds.length === 0 ? (
                  <div
                    data-testid="favorites-empty-state"
                    className="mt-7 rounded-[1.75rem] border border-dashed border-rose-200 bg-rose-50/50 px-5 py-12 text-center"
                  >
                    <div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-white text-rose-500 shadow-sm">
                      <Heart className="h-6 w-6" />
                    </div>
                    <h3 className="mt-5 text-lg font-black text-slate-900">
                      مفضلتك فارغة حاليًا
                    </h3>
                    <p className="mx-auto mt-2 max-w-md text-xs leading-6 text-slate-500">
                      أضف المنتجات التي تهمك عبر رمز القلب لتجدها هنا بسرعة.
                    </p>
                    <button
                      type="button"
                      onClick={showAllProducts}
                      className="mt-6 inline-flex min-h-11 items-center justify-center rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white transition hover:bg-blue-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700"
                    >
                      تصفح المنتجات
                    </button>
                  </div>
                ) : isLoading ? (
                  <div className="mt-7 grid grid-cols-2 gap-3 min-[380px]:grid-cols-3 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4">
                    {Array.from({ length: Math.min(4, favoriteProductIds.length) }).map((_, index) => (
                      <div
                        key={index}
                        className="h-[430px] animate-pulse rounded-[1.75rem] border border-slate-200 bg-slate-50 p-4"
                      >
                        <div className="h-52 rounded-3xl bg-slate-100" />
                        <div className="mt-5 h-4 w-2/3 rounded bg-slate-100" />
                        <div className="mt-3 h-3 w-1/3 rounded bg-slate-100" />
                      </div>
                    ))}
                  </div>
                ) : loadError && favoriteProducts.length === 0 ? (
                  <div className="mt-7 rounded-[1.75rem] border border-rose-200 bg-rose-50/50 p-8 text-center">
                    <AlertTriangle className="mx-auto h-9 w-9 text-rose-500" />
                    <h3 className="mt-4 text-base font-black text-slate-900">
                      تعذر تحديث المفضلة الآن
                    </h3>
                    <p className="mx-auto mt-2 max-w-md text-xs leading-6 text-slate-500">
                      لم نعرض معلومات قديمة عن السعر أو التوفر. حاول مرة أخرى.
                    </p>
                    <button
                      type="button"
                      onClick={() => void loadCatalog(false, true)}
                      className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white"
                    >
                      <RefreshCw className="h-4 w-4" />
                      إعادة المحاولة
                    </button>
                  </div>
                ) : favoriteProducts.length === 0 ? (
                  <div className="mt-7 rounded-[1.75rem] border border-amber-200 bg-amber-50/60 p-8 text-center">
                    <AlertTriangle className="mx-auto h-9 w-9 text-amber-600" />
                    <h3 className="mt-4 text-base font-black text-slate-900">
                      لا توجد منتجات مفضلة قابلة للعرض الآن
                    </h3>
                    <p className="mx-auto mt-2 max-w-md text-xs leading-6 text-slate-600">
                      قد تكون بعض المنتجات قد حُذفت أو لم تعد متاحة للبيع. أبقينا قائمتك محفوظة كما هي.
                    </p>
                    <button
                      type="button"
                      onClick={showAllProducts}
                      className="mt-5 inline-flex min-h-11 items-center justify-center rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white"
                    >
                      تصفح المنتجات
                    </button>
                  </div>
                ) : (
                  <>
                    {missingFavoriteProductCount > 0 && (
                      <div className="mt-6 flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs leading-6 text-amber-900">
                        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-700" />
                        <p>
                          بعض العناصر المحفوظة لم تعد متاحة للعرض حاليًا. أبقيناها في قائمتك ولم نحذفها تلقائيًا.
                        </p>
                      </div>
                    )}
                    <div
                      data-testid="favorites-products-grid"
                      className="mt-7 grid grid-cols-2 gap-3 min-[380px]:grid-cols-3 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4"
                    >
                      {favoriteProducts.map((product) => (
                        <ProductCard
                          key={product.id}
                          product={product}
                          cartQuantity={catalogCartQuantityByProduct.get(product.id) || 0}
                          reservedQuantity={reservedBaseUnits.get(product.id) ?? 0}
                          isFavorite={favoriteProductIds.includes(product.id)}
                          onAdd={addToCart}
                          onQuantityChange={updateCatalogCartQuantity}
                          onOpenDetails={openProductDetails}
                          onToggleFavorite={toggleProductFavorite}
                        />
                      ))}
                    </div>
                  </>
                )}
              </div>
            </div>
          </section>
        )}

        {activePage === 'home' && (
          <>
        <section className="border-y border-slate-200 bg-white py-12">
          <div className="mx-auto grid max-w-7xl gap-4 px-4 sm:grid-cols-3 lg:px-8">
            {[
              {
                icon: ShieldCheck,
                title: 'أسعار آمنة',
                text: 'الموقع يعرض سعر البيع فقط ولا يكشف تكلفة الشراء.',
              },
              {
                icon: Boxes,
                title: 'طرد أو باكيت',
                text: 'اختر الطرد أو الباكيت؛ أساس الكمية والسعر واضح بجانب كل زر.',
              },
              {
                icon: Truck,
                title: 'مخزون موحّد',
                text: 'إضافة المنتج وتعديل سعره من الإدارة ينعكسان على الكتالوج.',
              },
            ].map((benefit) => {
              const Icon = benefit.icon;
              return (
                <div
                  key={benefit.title}
                  className="flex items-start gap-3 rounded-3xl bg-slate-50 p-5"
                >
                  <div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-blue-100 text-blue-700">
                    <Icon className="h-5 w-5" />
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-slate-900">
                      {benefit.title}
                    </h3>
                    <p className="mt-1 text-[11px] leading-5 text-slate-500">
                      {benefit.text}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
          </>
        )}
      </main>

      <CategoryDrawer
        isOpen={categoriesOpen}
        categories={catalogCategories}
        selectedCategory={selectedCategory}
                totalProducts={catalogTotal}
        onClose={() => setCategoriesOpen(false)}
        onSelect={selectCatalogCategory}
      />

      <StoreFooter
        whatsappUrl={storeWhatsappUrl}
        onNavigate={navigateStorePage}
        onTrackOrder={() => setTrackingOpen(true)}
        onOpenPrivacy={() => setPrivacyPolicyOpen(true)}
      />

      {selectedProduct && (
        <ProductDetailsModal
          product={selectedProduct}
          initialVariantId={selectedProductVariantId ?? undefined}
          cartQuantityByProduct={cartQuantityByProduct}
          reservedBaseUnits={reservedBaseUnits}
          relatedProducts={relatedProducts}
          onClose={closeProductDetails}
          onAddQuantity={addQuantityToCart}
          onAddBaseUnit={addBaseUnitToCart}
          parcelOption={parcelOptionsByFamily.get(selectedProduct.id)}
          parcelOptionLoading={parcelOptionLoading}
          onOpenParcelBuilder={(familyProduct, option) =>
            setParcelBuilder({ familyProduct, option })
          }
          onOpenProduct={openProductDetails}
          storeWhatsAppNumber={storefrontSettings.whatsappNumber}
          isFavorite={favoriteProductIds.includes(selectedProduct.id)}
          onToggleFavorite={toggleProductFavorite}
          onOpenAssistant={() => setAssistantOpen(true)}
        />
      )}

      <GuidedStoreAssistant
        isOpen={assistantOpen}
        showFloatingButton={
          !selectedProduct &&
          !cartOpen &&
          !checkoutOpen &&
          !trackingOpen &&
          !privacyPolicyOpen
        }
        settings={settingsTrusted ? storefrontSettings : null}
        whatsappUrl={storeWhatsappUrl}
        onOpen={() => setAssistantOpen(true)}
        onClose={() => setAssistantOpen(false)}
        onBrowseProducts={showAllProducts}
        onOpenOffers={openPromotionOffers}
        onTrackOrder={() => setTrackingOpen(true)}
        hasCartItems={cartPackages > 0}
      />

      <CartDrawer
        isOpen={cartOpen}
        items={cartItems}
        onClose={() => setCartOpen(false)}
        onQuantityChange={updateCartQuantity}
        onRemove={(localLineId) =>
          !cartStorageRecovery &&
          !lockedLineIds.has(localLineId) &&
          setCartItems((items) =>
            items.filter((item) => item.localLineId !== localLineId)
          )
        }
        onEditParcel={editParcelInstance}
        onDuplicateParcel={duplicateParcel}
        onRemoveParcel={removeParcel}
        lockedParcelInstanceIds={lockedParcelIds}
        lockedLineIds={lockedLineIds}
        cartStorageRecovery={cartStorageRecovery}
        hasUnresolvedCheckoutAttempt={unresolvedCheckoutAttempt}
        onResolveCartRecovery={handleCartStorageRecovery}
        onClear={() => {
          if (cartStorageRecovery) {
            showToast('استخدم إجراء معالجة السلة بدل الحذف التلقائي.', 'info');
            return;
          }
          if (lockedLineIds.size > 0 || lockedParcelIds.size > 0) {
            showToast('لا يمكن إفراغ السلة قبل حسم محاولة الطلب الحالية.', 'info');
            return;
          }
          setCartItems([]);
        }}
        onCheckout={openCheckout}
        isRefreshingSnapshot={isRefreshingCart}
        snapshotNotice={cartSnapshotNotice}
        checkoutDisabled={!settingsTrusted || Boolean(cartStorageRecovery) || Boolean(commerceReview)}
        checkoutBlockedMessage={
          commerceReview
            ? commerceReview.message
            : cartStorageRecovery
            ? 'السلة المحفوظة تحتاج معالجة صريحة قبل إتمام الطلب.'
            : settingsUnavailable
            ? 'تعذر التحقق من إعدادات الطلب والتوصيل. لن نعرض رسومًا أو حدًا أدنى غير موثوقين.'
            : 'جارٍ التحقق من إعدادات الطلب والتوصيل.'
        }
        onRetryCheckoutSettings={
          settingsUnavailable
            ? () => void loadStorefrontSettings(true)
            : undefined
        }
      />

      <CheckoutModal
        isOpen={checkoutOpen}
        items={cartItems}
        storeWhatsAppNumber={storefrontSettings.whatsappNumber}
        storefrontSettings={storefrontSettings}
        settingsUnavailable={settingsUnavailable}
        initialPromotionCode={preferredPromotionCode}
        coordinator={checkoutCoordinator}
        onClose={() => setCheckoutOpen(false)}
        onRetryStorefrontSettings={() => void loadStorefrontSettings(true)}
        onOpenPrivacyPolicy={() => setPrivacyPolicyOpen(true)}
        onOrderCreated={handleOrderCreated}
        onTrackOrder={openCreatedOrderTracking}
      />

      {parcelBuilder && (
        <ParcelBuilderModal
          option={parcelBuilder.option}
          initialInstance={parcelBuilder.edit?.instance}
          reservedByProductId={reservedBaseUnits}
          onClose={() => setParcelBuilder(null)}
          onSave={saveParcelBuilder}
        />
      )}

      <OrderTrackingModal
        isOpen={trackingOpen}
        trackingToken={trackingToken}
        onClose={() => {
          setTrackingOpen(false);
          if (trackingToken) {
            window.history.replaceState(null, '', '/');
            window.dispatchEvent(new PopStateEvent('popstate'));
          }
        }}
      />

      <PrivacyPolicyModal
        isOpen={privacyPolicyOpen}
        onClose={() => setPrivacyPolicyOpen(false)}
        storeName={SEO_BRAND.officialName}
        whatsappNumber={storefrontSettings.whatsappNumber}
      />

      <MobileStoreNav cartPackages={cartPackages} cartSummary={formatCartQuantitySummary(cartItems)} cartTotal={cartSubtotal} whatsappUrl={storeWhatsappUrl} onHome={() => navigateStorePage('home')} onCategories={() => navigateStorePage('categories')} onSearch={() => { setActivePage('catalog'); changeStoreLocation(getStorePagePath('catalog')); setSearchOpenSignal((value) => value + 1); }} onCart={() => openCart()} />

      <FloatingContactActions whatsappUrl={storeWhatsappUrl} />

      {toast && (
        <div
          className={`fixed bottom-5 left-1/2 z-[70] flex -translate-x-1/2 items-center gap-2 rounded-2xl px-4 py-3 text-xs font-extrabold text-white shadow-2xl ${
            toast.type === 'error'
              ? 'bg-rose-600'
              : toast.type === 'info'
              ? 'bg-slate-800'
              : 'bg-emerald-600'
          }`}
        >
          {toast.type === 'error' ? (
            <AlertTriangle className="h-4 w-4" />
          ) : (
            <CheckCircle2 className="h-4 w-4" />
          )}
          {toast.message}
        </div>
      )}
    </div>
  );
}

