        </div>

        {!product.isAvailable && (
          <div className="absolute inset-0 grid place-items-center bg-slate-950/50 backdrop-blur-[2px]">
            <span className="rounded-xl bg-white px-2 py-1.5 text-[10px] font-black text-slate-800 sm:px-4 sm:py-2 sm:text-xs">
