import {
  Barcode,
  Boxes,
  CheckCircle2,
  CircleHelp,
  Copy,
  Heart,
  PackageCheck,
  Share2,
  Tag,
  X,
  ZoomIn,
  MessageCircle,
} from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import {useDialogFocus} from '../hooks/useDialogFocus';
import { CatalogProduct, PublicConfigurableParcelOption } from '../types/catalog';
import { formatJod } from '../utils/money';
import {ProductPurchaseControl} from './ProductPurchaseControl';
import {storefrontSaleUnit, storefrontPackageDescription, storefrontStock, storefrontUnitName, remainingStorefrontUnits, remainingStorefrontParcels} from '../utils/storefrontUnits';
import { ProductImage } from './ProductImage';
import {
  buildProductShareUrl,
  clampProductSelectionQuantity,
} from '../utils/productDetails';
import { buildWhatsAppUrl } from '../utils/checkout';

interface ProductDetailsModalProps {
  product: CatalogProduct;
  initialVariantId?: string;
  cartQuantityByProduct: ReadonlyMap<string, number>;
  reservedBaseUnits: ReadonlyMap<string, number>;
  relatedProducts: CatalogProduct[];
  onClose: () => void;
  onAddQuantity: (product: CatalogProduct, quantity: number) => void;
  onAddBaseUnit: (product: CatalogProduct, quantity: number) => void;
  parcelOption?: PublicConfigurableParcelOption;
  parcelOptionLoading?: boolean;
  onOpenParcelBuilder: (product: CatalogProduct, option: PublicConfigurableParcelOption) => void;
  onOpenProduct: (product: CatalogProduct) => void;
  storeWhatsAppNumber: string;
  isFavorite: boolean;
  onToggleFavorite: (product: CatalogProduct) => void;
  onOpenAssistant: () => void;
}

export function ProductDetailsModal({
  product: familyProduct,
  initialVariantId,
  cartQuantityByProduct,
  reservedBaseUnits,
  relatedProducts,
  onClose,
  onAddQuantity,
  onAddBaseUnit,
  parcelOption,
  parcelOptionLoading = false,
  onOpenParcelBuilder,
  onOpenProduct,
  storeWhatsAppNumber,
  isFavorite,
  onToggleFavorite,
  onOpenAssistant,
}: ProductDetailsModalProps) {
  const [selectedVariantId, setSelectedVariantId] = useState(
    () =>
      familyProduct.variants.find((variant) => variant.id === initialVariantId)
        ?.id ||
      familyProduct.variants.find((variant) => variant.isAvailable)?.id ||
      familyProduct.variants[0]?.id ||
      ''
  );
  const product =
    familyProduct.variants.find((variant) => variant.id === selectedVariantId) ||
    familyProduct;
  const cartQuantity = cartQuantityByProduct.get(product.id) || 0;
  const reserved = reservedBaseUnits.get(product.id) ?? 0;
  const remainingUnits = remainingStorefrontUnits(product, reserved);
  const remainingPackages = remainingStorefrontParcels(product, reserved);
  const [quantity, setQuantity] = useState(() => clampProductSelectionQuantity(product.minimumOrderPackages, remainingPackages, 0));
  const [unitQuantity, setUnitQuantity] = useState(() => clampProductSelectionQuantity(1, remainingUnits, 0));
  const [shareMessage, setShareMessage] = useState('');
  const [imageZoomed, setImageZoomed] = useState(false);
  const panel = useDialogFocus(true, () => {
    if (imageZoomed) setImageZoomed(false);
    else onClose();
  });

  useEffect(() => {
    setSelectedVariantId(
      familyProduct.variants.find((variant) => variant.id === initialVariantId)
        ?.id ||
        familyProduct.variants.find((variant) => variant.isAvailable)?.id ||
        familyProduct.variants[0]?.id ||
        ''
    );
  }, [familyProduct.id, familyProduct.variants, initialVariantId]);

  useEffect(() => {
    setQuantity(product.minimumOrderPackages);
    setUnitQuantity(1);
    setShareMessage('');
    setImageZoomed(false);
  }, [product.id, product.minimumOrderPackages]);

  useEffect(() => {
    setQuantity(current => clampProductSelectionQuantity(current, remainingPackages, 0));
    setUnitQuantity(current => clampProductSelectionQuantity(current, remainingUnits, 0));
  }, [product.id, remainingPackages, remainingUnits]);

  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';


    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [onClose]);

  const packageDescription = storefrontPackageDescription(product);
  const shareUrl = useMemo(
    () =>
      buildProductShareUrl(
        window.location.href,
        product.sku || product.id
      ),
    [product.id, product.sku]
  );

  const handleShare = async () => {
    const shareText = `${product.nameAr} — سعر ${storefrontSaleUnit(product)} ${formatJod(
      product.salePackagePriceInMinorUnits
    )}`;

    try {
      if (navigator.share) {
        await navigator.share({
          title: product.nameAr,
          text: shareText,
          url: shareUrl,
        });
        setShareMessage('تم فتح خيارات المشاركة.');
        return;
      }

      if (navigator.clipboard) {
        await navigator.clipboard.writeText(shareUrl);
        setShareMessage('تم نسخ رابط المنتج.');
        return;
      }

      setShareMessage('انسخ رابط المنتج من شريط المتصفح.');
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') return;
      setShareMessage('تعذرت المشاركة. انسخ الرابط من شريط المتصفح.');
    }
  };

  const shareOnWhatsApp = () => {
    const text = `${product.nameAr} — سعر ${storefrontSaleUnit(product)} ${formatJod(product.salePackagePriceInMinorUnits)}\n${shareUrl}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank', 'noopener,noreferrer');
  };

  const handleQuantityChange = (nextQuantity: number) => {
    setQuantity(
      clampProductSelectionQuantity(
        nextQuantity,
        remainingPackages,
        0
      )
    );
  };

  const handleAdd = () => {
    if (quantity < 1 || remainingPackages < 1) return;
    onAddQuantity(product, quantity);
  };

  const isLowStock =
    product.isAvailable && product.availableSalePackages <= 2;

  return (
    <div className="fixed inset-0 z-[55]" dir="rtl">
      <button
        type="button"
        aria-label="إغلاق تفاصيل المنتج"
        onClick={onClose}
        className="absolute inset-0 bg-slate-950/65 backdrop-blur-sm"
      />

      <section
        ref={panel}
        tabIndex={-1}
        role="dialog"
        aria-modal="true"
        aria-labelledby="product-details-title"
        className="absolute inset-0 flex flex-col overflow-hidden bg-white shadow-2xl sm:inset-x-6 sm:top-1/2 sm:mx-auto sm:h-auto sm:max-h-[94vh] sm:max-w-5xl sm:-translate-y-1/2 sm:rounded-[2rem]"
      >
        <header className="z-10 flex shrink-0 items-center justify-between border-b border-slate-100 bg-white/95 px-4 py-3 backdrop-blur sm:px-6 sm:py-4">
          <div className="min-w-0">
            <p className="text-[10px] font-extrabold text-blue-600">
              تفاصيل صنف الجملة
            </p>
            <h2
              id="product-details-title"
              className="mt-1 truncate text-base font-black text-slate-950 sm:text-lg"
            >
              {product.nameAr}
            </h2>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => onToggleFavorite(familyProduct)}
              aria-label={
                isFavorite
                  ? `إزالة ${familyProduct.nameAr} من المفضلة`
                  : `إضافة ${familyProduct.nameAr} إلى المفضلة`
              }
              aria-pressed={isFavorite}
              className={`grid h-10 w-10 place-items-center rounded-2xl border transition ${
                isFavorite
                  ? 'border-rose-200 bg-rose-600 text-white'
                  : 'border-slate-200 bg-white text-slate-600 hover:border-rose-200 hover:bg-rose-50 hover:text-rose-600'
              }`}
            >
              <Heart
                className={`h-4 w-4 ${isFavorite ? 'fill-current' : ''}`}
              />
            </button>
            <button
              type="button"
              onClick={() => void handleShare()}
              aria-label="مشاركة المنتج"
              className="grid h-10 w-10 place-items-center rounded-2xl border border-slate-200 bg-white text-blue-700 transition hover:bg-blue-50"
            >
              <Share2 className="h-4 w-4" />
            </button>
            <button
              type="button"
              onClick={onOpenAssistant}
              aria-label="فتح مساعد المتجر"
              className="grid h-10 w-10 place-items-center rounded-2xl border border-amber-200 bg-amber-50 text-amber-800 transition hover:bg-amber-100"
            >
              <CircleHelp className="h-4 w-4" />
            </button>
            <button type="button" onClick={shareOnWhatsApp} aria-label="مشاركة المنتج على واتساب" className="grid h-10 w-10 place-items-center rounded-2xl border border-emerald-200 bg-emerald-50 text-emerald-700"><MessageCircle className="h-4 w-4" /></button>
            <button
              type="button"
              onClick={onClose}
              aria-label="إغلاق"
              className="grid h-10 w-10 place-items-center rounded-2xl bg-slate-100 text-slate-600 transition hover:bg-slate-200"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </header>

        <div className="min-h-0 flex-1 overflow-y-auto">
          <div className="grid sm:grid-cols-[0.9fr_1.1fr]">
            <div className="bg-gradient-to-br from-slate-50 via-white to-blue-50 p-4 sm:p-7">
              <button type="button" onClick={() => setImageZoomed((value) => !value)} aria-label={imageZoomed ? 'تصغير صورة المنتج' : 'تكبير صورة المنتج'} className="relative mx-auto block aspect-[4/3] max-h-[46vh] w-full overflow-hidden rounded-[2rem] border border-white bg-white shadow-[0_24px_70px_-44px_rgba(15,23,42,0.7)] sm:aspect-square sm:max-h-[440px]">
                <ProductImage
                  src={product.imageUrl}
                  alt={product.nameAr}
                  imageClassName={`h-full w-full object-contain p-3 transition duration-300 sm:p-5 ${imageZoomed ? 'scale-150' : 'scale-100'}`}
                  fallbackClassName="grid h-full place-items-center text-center text-slate-400"
                  fallbackLabel="لا توجد صورة لهذا المنتج بعد"
                />

                <span className="absolute right-4 top-4 rounded-2xl border border-white/80 bg-white/90 px-3 py-2 text-[10px] font-black text-blue-800 shadow-sm backdrop-blur">
                  {product.categoryNameAr}
                </span>
                {product.imageUrl && <span className="absolute bottom-4 left-4 grid h-9 w-9 place-items-center rounded-2xl bg-slate-950/70 text-white"><ZoomIn className="h-4 w-4" /></span>}
              </button>
            </div>

            <div className="p-5 sm:border-r sm:border-slate-100 sm:p-7">
              <div className="flex flex-wrap items-center gap-2">
                {product.brandNameAr && (
                  <span className="rounded-full bg-blue-50 px-3 py-1.5 text-[10px] font-black text-blue-700">
                    {product.brandNameAr}
                  </span>
                )}
                <span
                  className={`rounded-full px-3 py-1.5 text-[10px] font-black ${
                    product.isAvailable
                      ? isLowStock
                        ? 'bg-amber-100 text-amber-800'
                        : 'bg-emerald-100 text-emerald-700'
                      : 'bg-rose-100 text-rose-700'
                  }`}
                >
                  {product.isAvailable
                    ? isLowStock
                      ? 'كمية محدودة'
                      : 'متوفر الآن'
                    : 'غير متوفر حاليًا'}
                </span>
              </div>

              <h3 className="mt-4 text-2xl font-black leading-tight text-slate-950 sm:text-3xl">
                {product.nameAr}
              </h3>

              {product.description ? (
                <p className="mt-3 text-xs font-semibold leading-7 text-slate-600 sm:text-sm">
                  {product.description}
                </p>
              ) : (
                <p className="mt-3 text-xs font-semibold leading-6 text-slate-400">
                  السعر والمخزون موضحان أدناه.
                </p>
              )}

              {familyProduct.variants.length > 0 && (
                <div className="mt-5 rounded-3xl border border-violet-100 bg-violet-50/70 p-4">
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <p className="text-[10px] font-black text-violet-700">
                        اختر النكهة
                      </p>
                      <p className="mt-1 text-[9px] font-bold text-slate-500">
                        السعر نفسه، والتوفر محسوب لكل نكهة وحدها
                      </p>
                    </div>
                    <span className="rounded-full bg-white px-2.5 py-1 text-[9px] font-black text-violet-700 shadow-sm">
                      {familyProduct.variants.filter((variant) => variant.isAvailable).length.toLocaleString('ar-JO')} متوفرة
                    </span>
                  </div>
                  <div className="mt-3 flex gap-2 overflow-x-auto pb-1">
                    {familyProduct.variants.map((variant) => {
                      const selected = variant.id === product.id;
                      return (
                        <button
                          type="button"
                          key={variant.id}
                          onClick={() => setSelectedVariantId(variant.id)}
                          className={`min-w-[7.5rem] shrink-0 rounded-2xl border p-2.5 text-right transition ${
                            selected
                              ? 'border-violet-500 bg-violet-700 text-white shadow-md'
                              : variant.isAvailable
                                ? 'border-violet-100 bg-white text-slate-800'
                                : 'border-slate-200 bg-slate-100 text-slate-400'
                          }`}
                        >
                          <div className="flex items-center gap-2">
                            <div className="h-9 w-9 shrink-0 overflow-hidden rounded-xl bg-white/80">
                              <ProductImage
                                src={variant.imageUrl}
                                alt={variant.flavorNameAr}
                                imageClassName="h-full w-full object-contain"
                                fallbackClassName="grid h-full place-items-center text-violet-400"
                              />
                            </div>
                            <div className="min-w-0">
                              <strong className="block truncate text-[10px] font-black">
                                {variant.flavorNameAr}
                              </strong>
                              <span className={`mt-0.5 block text-[8px] font-bold ${selected ? 'text-violet-100' : variant.isAvailable ? 'text-emerald-600' : 'text-rose-500'}`}>
                                {variant.isAvailable
                                  ? `${variant.availableSalePackages.toLocaleString('ar-JO')} ${storefrontSaleUnit(variant)}`
                                  : 'نافدة حاليًا'}
                              </span>
                            </div>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="mt-5 rounded-3xl border border-orange-100 bg-orange-50 p-4">
                <p className="text-[10px] font-bold text-orange-500">
                  سعر {storefrontSaleUnit(product)}
                </p>
                <p className="mt-1 text-3xl font-black text-orange-700">
                  {formatJod(product.salePackagePriceInMinorUnits)}
                </p>
                <p className="mt-1 text-[10px] font-bold text-orange-700/70">
                  السعر لوحدة البيع: {storefrontSaleUnit(product)}
                </p>
              </div>

              {product.unitsPerSalePackage > 1 && <div className="mt-4 grid grid-cols-2 gap-3">
                <div className="rounded-3xl border border-blue-100 bg-blue-50 p-4">
                  <div className="flex items-center gap-2 text-blue-600">
                    <Boxes className="h-4 w-4" />
                    <p className="text-[10px] font-bold">طرد البيع</p>
                  </div>
                  <p className="mt-2 text-sm font-black text-blue-950">
                    {storefrontSaleUnit(product)}
                  </p>
                </div>
                <div className="rounded-3xl border border-slate-200 bg-slate-50 p-4">
                  <div className="flex items-center gap-2 text-slate-500">
                    <PackageCheck className="h-4 w-4" />
                    <p className="text-[10px] font-bold">محتوى الطرد</p>
                  </div>
                  <p className="mt-2 text-sm font-black text-slate-900">
                    {product.unitsPerSalePackage.toLocaleString('ar-JO')}{' '}
                    {product.unitNameAr}
                  </p>
                </div>
              </div>}

              <div className="mt-4 rounded-3xl border border-emerald-100 bg-emerald-50 p-4">
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <p className="text-[10px] font-bold text-emerald-700">
                      المتوفر للطلب الآن
                    </p>
                    <p className="mt-1 text-base font-black text-emerald-950">
                      {storefrontStock(product)}
                    </p>
                  </div>
                  <CheckCircle2 className="h-6 w-6 text-emerald-600" />
                </div>
                {cartQuantity > 0 && (
                  <p className="mt-2 text-[10px] font-bold text-emerald-700">
                    في سلتك حاليًا: {cartQuantity.toLocaleString('ar-JO')} {storefrontSaleUnit(product)}
                  </p>
                )}
              </div>

              <div className="mt-5 border-t border-slate-100 pt-5">
                <p className="text-[10px] font-black text-slate-500">
                  معلومات التعريف
                </p>
                <div className="mt-3 grid gap-2 text-[10px] font-bold text-slate-600 sm:grid-cols-2">
                  <div className="flex items-center gap-2 rounded-2xl bg-slate-50 px-3 py-2.5">
                    <Tag className="h-3.5 w-3.5 text-blue-600" />
                    <span>SKU:</span>
                    <span dir="ltr" className="font-mono text-slate-900">
                      {product.sku}
                    </span>
                  </div>
                  {product.barcode && (
                    <div className="flex items-center gap-2 rounded-2xl bg-slate-50 px-3 py-2.5">
                      <Barcode className="h-3.5 w-3.5 text-blue-600" />
                      <span dir="ltr" className="font-mono text-slate-900">
                        {product.barcode}
                      </span>
                    </div>
                  )}
                </div>
              </div>

              {shareMessage && (
                <div className="mt-4 flex items-center gap-2 rounded-2xl border border-blue-100 bg-blue-50 px-3 py-2.5 text-[10px] font-bold text-blue-800">
                  <Copy className="h-3.5 w-3.5" />
                  {shareMessage}
                </div>
              )}
            </div>
          </div>

          {relatedProducts.length > 0 && (
            <div className="border-t border-slate-100 bg-slate-50/80 px-5 py-6 sm:px-7">
              <div className="flex items-end justify-between gap-3">
                <div>
                  <p className="text-[10px] font-black text-blue-600">
                    من نفس القسم
                  </p>
                  <h3 className="mt-1 text-base font-black text-slate-950">
                    أصناف مشابهة
                  </h3>
                </div>
                <p className="text-[9px] font-bold text-slate-400">
                  اضغط لعرض التفاصيل
                </p>
              </div>

              <div className="mt-4 flex gap-3 overflow-x-auto pb-2">
                {relatedProducts.map((relatedProduct) => (
                  <button
                    type="button"
                    key={relatedProduct.id}
                    onClick={() => onOpenProduct(relatedProduct)}
                    className="flex w-64 shrink-0 items-center gap-3 rounded-3xl border border-slate-200 bg-white p-3 text-right transition hover:border-blue-200 hover:shadow-md"
                  >
                    <div className="h-16 w-16 shrink-0 overflow-hidden rounded-2xl bg-slate-100">
                      <ProductImage
                        src={relatedProduct.imageUrl}
                        alt={relatedProduct.nameAr}
                        imageClassName="h-full w-full object-contain p-1"
                      />
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-xs font-black text-slate-900">
                        {relatedProduct.nameAr}
                      </p>
                      <p className="mt-1 text-[9px] font-bold text-slate-400">
                        {storefrontSaleUnit(relatedProduct)}
                      </p>
                      <p className="mt-1 text-xs font-black text-orange-700">
                        {formatJod(
                          relatedProduct.salePackagePriceInMinorUnits
                        )}
                      </p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <footer role="group" aria-label="إضافة المنتج للسلة" className="shrink-0 border-t border-slate-100 bg-white px-4 pb-[max(1rem,env(safe-area-inset-bottom))] pt-3 sm:px-7 sm:py-4">
          <div className={`mx-auto grid max-w-3xl gap-2 ${!product.parcelOnly&&product.unitsPerSalePackage > 1 ? 'grid-cols-2' : 'grid-cols-1'}`}>
            <ProductPurchaseControl label={packageDescription} unit={storefrontSaleUnit(product)} productName={product.nameAr}
              price={product.salePackagePriceInMinorUnits} quantity={quantity} remaining={remainingPackages}
              disabled={!product.isAvailable} onChange={handleQuantityChange} onAdd={handleAdd} />
            {!product.parcelOnly&&product.unitsPerSalePackage > 1 && <ProductPurchaseControl label={storefrontUnitName(product.unitNameAr)} unit={storefrontUnitName(product.unitNameAr)} productName={product.nameAr}
              price={product.salePriceInMinorUnits} quantity={unitQuantity} remaining={remainingUnits}
              disabled={product.salePriceInMinorUnits <= 0 || remainingUnits === 0}
              onChange={next => setUnitQuantity(clampProductSelectionQuantity(next, remainingUnits, 0))}
              onAdd={() => onAddBaseUnit(product, unitQuantity)} />}
          </div>
          {familyProduct.variants.length > 0 && parcelOption && <button type="button"
            onClick={() => parcelOption && onOpenParcelBuilder(familyProduct, parcelOption)}
            disabled={!parcelOption || parcelOptionLoading}
            className="mx-auto mt-2 block min-h-11 w-full max-w-3xl rounded-2xl bg-violet-700 px-3 text-xs font-black text-white disabled:bg-slate-300 disabled:text-slate-700">
            {parcelOptionLoading ? 'جارٍ تحميل خيارات الطرد...' : 'كوّن طردًا بالنكهات'}
          </button>}
          {!product.isAvailable && <a href={buildWhatsAppUrl(storeWhatsAppNumber, `مرحبًا، أريد الاستفسار عن توفر ${product.nameAr} (${product.sku}).`)} target="_blank" rel="noreferrer" className="mx-auto mt-2 flex min-h-11 max-w-3xl items-center justify-center gap-2 rounded-2xl bg-emerald-700 px-4 text-xs font-black text-white"><MessageCircle className="h-4 w-4" />اسألنا على واتساب</a>}
          <p className="mt-2 text-center text-[9px] font-bold text-slate-600">
            {packageDescription} • تُراجع الكمية والسعر مرة أخرى عند إرسال الطلب
          </p>
        </footer>
      </section>
    </div>
  );
}

