  isRefreshing: boolean;
  suggestions: CatalogProduct[];
  searchOpenSignal: number;
  onSuggestionSelect: (product: CatalogProduct) => void;
}

export function StoreHeader({
  activePage,
  searchQuery,
  onSearchChange,
  cartPackages,
  cartSummary,
  favoritesCount,
  favoritesActive,
  onCartOpen,
  onFavoritesOpen,
  onMenuOpen,
  onCategoriesOpen,
  onHome,
  onAllProducts,
  onOffers,
  onAbout,
  onTrackOrder,
  onRefresh,
  isRefreshing,
  suggestions,
  searchOpenSignal,
  onSuggestionSelect,
