import {checkLayout} from './package-f-layout';
const url=(view='create-direct',theme='light',extra='')=>`/e2e/package-f-purchasing-harness.html?purchase205=1&view=${view}&theme=${theme}${extra}`;
const quote={receiptId:'88888888-8888-4888-8888-000000002050',receiptNumber:'GRN-205-LATEST',source:'direct',receivedAt:'2026-10-20T08:00:00Z',supplierId:null,supplierName:null,grossInMinorUnits:100000,baseQuantity:200,baseUnitName:'باكيت'};
async function reads(page:Page){
  await page.route('**/rest/v1/rpc/get_receiving_purchase_context',route=>route.fulfill({status:200,json:{products:(route.request().postDataJSON().p_product_ids as string[]).map(productId=>({productId,lastPurchase:quote}))}}));
}
async function addProduct(page:Page){const input=page.getByRole('textbox',{name:/ابحث/}).first();await input.fill('عصير');await page.locator('[data-receiving-product-result]').first().click();return page.locator('[data-receiving-line]').last();}
for(const theme of ['light','dark'])for(const width of [390,1440])test(`205 receiving ${theme}/${width}: last quote,folded contents,price-rise,layout and axe`,async({page})=>{
  await reads(page);await page.setViewportSize({width,height:900});await page.goto(url('create-direct',theme));const row=await addProduct(page);
  await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('5');await expect(row.getByText(/آخر سعر شراء: 5.000/)).toBeVisible();
  await expect(row.getByLabel('كم باكيت بالطرد؟',{exact:true})).toHaveCount(0);await expect(row.getByText('الطرد فيه 10 باكيت',{exact:true})).toBeVisible();await expect(row.getByLabel('نوع الطرد')).toHaveCount(0);
  await row.getByRole('button',{name:'تعديل محتوى الطرد'}).click();await expect(row.getByLabel('كم باكيت بالطرد؟',{exact:true})).toHaveValue('10');await row.getByRole('button',{name:'تم',exact:true}).click();
  await row.getByLabel('سعر طرد',{exact:true}).fill('7');await expect(row.getByText(/سعر البيع أقل من الشراء الجديد/)).toBeVisible();
  await row.getByRole('button',{name:'لا',exact:true}).click();await expect(row.getByText(/سعر الشراء ارتفع من/)).toHaveCount(0);
  await row.getByRole('radio',{name:'باكيت',exact:true}).click();await expect(row.getByLabel('سعر باكيت',{exact:true})).toHaveValue('0.5');
  await row.getByRole('radio',{name:'طرد',exact:true}).click();await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('5');
  await checkLayout(page,page.getByTestId('purchasing-workbench'));const audit=await analyzePackageFAccessibility(page,new AxeBuilder({page}));expect(audit.violations.filter(v=>v.impact==='serious'||v.impact==='critical')).toEqual([]);
});
test('205 late quote cannot overwrite edited price or quantity;repeated product rows keep independent prices',async({page})=>{
  let release!:()=>void;const pending=new Promise<void>(resolve=>{release=resolve;});let requested=false;
  await page.route('**/rest/v1/rpc/get_receiving_purchase_context',async route=>{requested=true;await pending;return route.fulfill({status:200,json:{products:route.request().postDataJSON().p_product_ids.map((productId:string)=>({productId,lastPurchase:quote}))}});});
  await page.goto(url());let row=await addProduct(page);await expect.poll(()=>requested).toBe(true);await row.getByLabel('سعر طرد',{exact:true}).fill('7');await row.getByLabel('كم طرد؟',{exact:true}).fill('20');release();await expect(row.getByText(/آخر سعر شراء:/)).toBeVisible();await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('7');await expect(row.getByLabel('كم طرد؟',{exact:true})).toHaveValue('20');
  row=await addProduct(page);await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('5');await expect(page.locator('[data-receiving-line]').first().getByLabel('سعر طرد',{exact:true})).toHaveValue('7');
});
test('205 nested existing optimistic product save preserves receipt and supports a product absent from bounded store cache',async({page})=>{
  await reads(page);let saved:Record<string,unknown>|undefined;const receipts:Record<string,unknown>[]=[];
  await page.route('**/rest/v1/rpc/update_product_master_v5',async route=>{saved=route.request().postDataJSON();await page.evaluate(()=>{(window as unknown as {__receiving205UpdateSale:(price:number)=>void}).__receiving205UpdateSale(800);});return route.fulfill({status:200,json:{success:true,productId:saved!.p_product_id,updatedAt:'2026-10-20T09:00:00Z'}});});
  await page.route('**/rest/v1/rpc/create_direct_supplier_receipt_v2',route=>{receipts.push(route.request().postDataJSON());return route.fulfill({status:400,json:{code:'P0001',message:'ISOLATED_RECEIPT_CAPTURE'}});});
  await page.goto(url());const row=await addProduct(page);await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('5');await row.getByLabel('كم طرد؟',{exact:true}).fill('20');await row.getByLabel('سعر طرد',{exact:true}).fill('7');
  expect(await page.evaluate(()=>(window as unknown as {__receiving205CachedProducts:()=>number}).__receiving205CachedProducts())).toBe(0);
  await row.getByRole('button',{name:'تعديل سعر البيع'}).click();const editor=page.getByRole('dialog',{name:'تعديل سعر البيع مع إبقاء الاستلام'});await expect(editor.getByLabel('سعر بيع الطرد',{exact:true})).toHaveValue('6');await editor.getByLabel('سعر بيع الطرد',{exact:true}).fill('8');await editor.getByRole('button',{name:'حفظ التعديلات',exact:true}).click();await expect(editor).toHaveCount(0);await expect.poll(()=>saved?.p_expected_updated_at).toBe('2026-10-20T08:00:00Z');
  await expect(row.getByLabel('كم طرد؟',{exact:true})).toHaveValue('20');await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('7');await expect(row.getByText(/ربح الطرد التقريبي صار 1.000 بدل 3.000/)).toBeVisible();
  await page.getByRole('button',{name:'حفظ واستلام البضاعة',exact:true}).click();await expect.poll(()=>receipts.length).toBe(1);expect(receipts[0].p_lines).toEqual([expect.objectContaining({line_kind:'base_unit',commercial_quantity:200,gross_amount_in_minor_units:140000,components:[expect.objectContaining({base_quantity:200})]})]);
});
test('205 accountant can read the last purchase but cannot enter product-price editing;missing capability is explicit',async({page})=>{
  await reads(page);await page.goto(url('create-direct','light','&role=accountant'));const row=await addProduct(page);await expect(row.getByLabel('سعر طرد',{exact:true})).toHaveValue('5');await row.getByLabel('سعر طرد',{exact:true}).fill('7');await expect(row.getByText(/سعر الشراء ارتفع/)).toBeVisible();await expect(row.getByRole('button',{name:'تعديل سعر البيع'})).toHaveCount(0);
