                )}
                {entry.isReversed
                  ? <StatusBadge tone="mute">معكوس</StatusBadge>
                  : <UiButton variant="danger" disabled={disabled} onClick={() => { setTarget(entry); setReason(''); setError(''); }}
                      aria-label={`عكس الرصيد ${entry.entryNumber}`}>عكس</UiButton>}
